INSERT INTO document_templates (id, tenant_id, establishment_id, type_code, locale, html, version, validated_at, created_by, created_at) VALUES ('01PRIDT01F0000000000000000', '*', '', 'pri_school_certificate', 'fr', '<html><body><h1>{{establishment_name}}</h1><h2>Certificat de scolarité</h2><p>Nous soussignés certifions que <strong>{{holder_name}}</strong> est régulièrement inscrit(e) en classe de {{class_name}} ({{level_name}}) pour l’année scolaire {{academic_year}}.</p><p>Fait le {{issued_on}}.</p><div>{{signature}}{{stamp}}</div><p>Numéro : {{number}}</p><div>{{qr}}</div><p>Vérification : {{verification_url}}</p></body></html>', 1, '2026-10-21T14:00:00+01:00', NULL, '2026-10-21T14:00:00+01:00');
INSERT INTO document_templates (id, tenant_id, establishment_id, type_code, locale, html, version, validated_at, created_by, created_at) VALUES ('01PRIDT01E0000000000000000', '*', '', 'pri_school_certificate', 'en', '<html><body><h1>{{establishment_name}}</h1><h2>School attendance certificate</h2><p>We certify that <strong>{{holder_name}}</strong> is duly enrolled in class {{class_name}} ({{level_name}}) for the school year {{academic_year}}.</p><p>Issued on {{issued_on}}.</p><div>{{signature}}{{stamp}}</div><p>Number : {{number}}</p><div>{{qr}}</div><p>Verification : {{verification_url}}</p></body></html>', 1, '2026-10-21T14:00:00+01:00', NULL, '2026-10-21T14:00:00+01:00');
