INSERT INTO document_templates (id, tenant_id, establishment_id, type_code, locale, html, version, validated_at, created_by, created_at) VALUES ('01PRIDT02F0000000000000000', '*', '', 'pri_attendance_letter', 'fr', '<html><body><h1>{{establishment_name}}</h1><h2>Attestation de fréquentation</h2><p>Nous attestons que <strong>{{holder_name}}</strong> fréquente notre école en classe de {{class_name}} ({{level_name}}) durant l’année scolaire {{academic_year}}.</p><p>Fait le {{issued_on}}.</p><div>{{signature}}{{stamp}}</div><p>Numéro : {{number}}</p><div>{{qr}}</div><p>Vérification : {{verification_url}}</p></body></html>', 1, '2026-10-21T14:00:00+01:00', NULL, '2026-10-21T14:00:00+01:00');
INSERT INTO document_templates (id, tenant_id, establishment_id, type_code, locale, html, version, validated_at, created_by, created_at) VALUES ('01PRIDT02E0000000000000000', '*', '', 'pri_attendance_letter', 'en', '<html><body><h1>{{establishment_name}}</h1><h2>Attendance letter</h2><p>We attest that <strong>{{holder_name}}</strong> attends our school in class {{class_name}} ({{level_name}}) during the school year {{academic_year}}.</p><p>Issued on {{issued_on}}.</p><div>{{signature}}{{stamp}}</div><p>Number : {{number}}</p><div>{{qr}}</div><p>Verification : {{verification_url}}</p></body></html>', 1, '2026-10-21T14:00:00+01:00', NULL, '2026-10-21T14:00:00+01:00');
