INSERT INTO document_templates (id, tenant_id, establishment_id, type_code, locale, html, version, validated_at, created_by, created_at) VALUES ('01PRIDT04F0000000000000000', '*', '', 'pri_info_sheet', 'fr', '<html><body><h1>{{establishment_name}}</h1><h2>Fiche de renseignements</h2><p>Élève : <strong>{{holder_name}}</strong>, classe {{class_name}} ({{level_name}}), année {{academic_year}}. Responsables : {{guardians}}. Contact : {{contact_phone}}.</p><p>Fait le {{issued_on}}.</p><div>{{signature}}{{stamp}}</div><p>Numéro : {{number}}</p><p>Vérification : {{verification_url}}</p></body></html>', 1, '2026-10-21T14:00:00+01:00', NULL, '2026-10-21T14:00:00+01:00');
INSERT INTO document_templates (id, tenant_id, establishment_id, type_code, locale, html, version, validated_at, created_by, created_at) VALUES ('01PRIDT04E0000000000000000', '*', '', 'pri_info_sheet', 'en', '<html><body><h1>{{establishment_name}}</h1><h2>Information sheet</h2><p>Pupil: <strong>{{holder_name}}</strong>, class {{class_name}} ({{level_name}}), year {{academic_year}}. Guardians: {{guardians}}. Contact: {{contact_phone}}.</p><p>Issued on {{issued_on}}.</p><div>{{signature}}{{stamp}}</div><p>Number : {{number}}</p><p>Verification : {{verification_url}}</p></body></html>', 1, '2026-10-21T14:00:00+01:00', NULL, '2026-10-21T14:00:00+01:00');
