INSERT INTO document_templates (id, tenant_id, establishment_id, type_code, locale, html, version, validated_at, created_by, created_at) VALUES ('01PRIDT05F0000000000000000', '*', '', 'pri_transfer', 'fr', '<html><body><h1>{{establishment_name}}</h1><h2>Certificat de radiation (transfert)</h2><p>Nous certifions que <strong>{{holder_name}}</strong>, élève de {{class_name}} ({{level_name}}) en {{academic_year}}, quitte notre établissement le {{effective_on}} à destination de : {{destination}}. Motif : {{reason}}.</p><p>Fait le {{issued_on}}.</p><div>{{signature}}{{stamp}}</div><p>Numéro : {{number}}</p><div>{{qr}}</div><p>Vérification : {{verification_url}}</p></body></html>', 1, '2026-10-21T14:00:00+01:00', NULL, '2026-10-21T14:00:00+01:00');
INSERT INTO document_templates (id, tenant_id, establishment_id, type_code, locale, html, version, validated_at, created_by, created_at) VALUES ('01PRIDT05E0000000000000000', '*', '', 'pri_transfer', 'en', '<html><body><h1>{{establishment_name}}</h1><h2>Transfer certificate</h2><p>We certify that <strong>{{holder_name}}</strong>, pupil of {{class_name}} ({{level_name}}) in {{academic_year}}, leaves our school on {{effective_on}} for: {{destination}}. Reason: {{reason}}.</p><p>Issued on {{issued_on}}.</p><div>{{signature}}{{stamp}}</div><p>Number : {{number}}</p><div>{{qr}}</div><p>Verification : {{verification_url}}</p></body></html>', 1, '2026-10-21T14:00:00+01:00', NULL, '2026-10-21T14:00:00+01:00');
